        ]
    }},
    "negative_tendencies": {{
        "overview": "负向性格倾向的总体分析（100-150字，结合命理依据）",
        "details": [
            {{"title": "AI生成的两个字标题1", "description": "一句话总结这个倾向的表现和改善建议（15个字以内）"}},
            {{"title": "AI生成的两个字标题2", "description": "一句话总结这个倾向的表现和改善建议（15个字以内）"}},
