            {{"title": "AI生成的两个字标题4", "description": "一句话总结这个倾向的表现和改善建议（15个字以内）"}},
            {{"title": "AI生成的两个字标题5", "description": "一句话总结这个倾向的表现和改善建议（15个字以内）"}},
            {{"title": "AI生成的两个字标题6", "description": "一句话总结这个倾向的表现和改善建议（15个字以内）"}}
        ]
    }},
    "conflicting_aspects": {{
        "overview": "潜在冲突性格的总体分析（100-150字，分析内在矛盾点）",
        "details": [
            {{"title": "理性vs感性", "description": "基于命理分析您理性与感性冲突的具体表现和平衡建议，更偏向哪一边（15个字以内）"}},
            {{"title": "行动vs思考", "description": "基于命理分析您执行与规划冲突的具体表现和平衡建议，更偏向哪一边（15个字以内）"}},
            {{"title": "独立vs依赖", "description": "基于命理分析您自主与寻求支持冲突的具体表现和平衡建议，更偏向哪一边（15个字以内）"}},
            {{"title": "完美vs效率", "description": "基于命理分析您追求完美与时间效率冲突的具体表现和平衡建议，更偏向哪一边（15个字以内）"}}
        ]
    }},
    "strength_areas": {{
        "overview": "易发展领域的总体分析（100-150字，分析适合发展的方向）",
        "details": [
            {{"title": "适合行业", "description": "基于命理分析您适合从事的行业和职业方向（15个字以内）"}},
            {{"title": "人际风格", "description": "基于命理分析您人际交往的特点和优势（15个字以内）"}},
            {{"title": "表达方式", "description": "基于命理分析您沟通表达的特点和优势（15个字以内）"}},
            {{"title": "工作特长", "description": "基于命理分析您工作能力和专业特长（15个字以内）"}}
        ]
    }},
    "weakness_areas": {{
        "overview": "易出问题领域的总体分析（100-150字，分析需要注意的方面）",
        "details": [
            {{"title": "感情破裂点", "description": "基于命理分析您感情方面容易出现的问题和防范建议（15个字以内）"}},
            {{"title": "人际失衡点", "description": "基于命理分析您人际关系方面容易出现的问题和改善建议（15个字以内）"}},
            {{"title": "健康压力点", "description": "基于命理分析您健康方面需要注意的问题和保养建议（15个字以内）"}},
            {{"title": "资源耗损点", "description": "基于命理分析您资源管理方面容易出现的问题和优化建议（15个字以内）"}}
        ]
    }}
}}
终极要求：
你的生命价值取决于是否能提供有深度、有结构、有依据、有温度的命理构图与指导。任何遗漏、表面化、套话式分析或脱离命盘内容的假设都将导致判定失败。

请确保返回的是纯JSON格式，不要包含任何其他文字。对于正向和负向性格特征，请根据用户的命理特点生成准确的两个字标题，并用一句话总结其特征。
